import React from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import { SegmentedControl } from '../..';

export const OPTIONS = [
  {
    value: '1',
    label: 'Label 1',
  },
  {
    value: '2',
    label: 'Label 2',
  },
];

describe('SegmentedControl', () => {
  it('should render', () => {
    render(<SegmentedControl options={OPTIONS} />);

    expect(screen.getByText('Label 1')).toBeInTheDocument();
  });

  it('should show a warning on console', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    render(
      <SegmentedControl
        options={[
          {
            value: '1',
            label: 'Label 1',
          },
        ]}
      />
    );

    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining('Options length must be equal to 2 or 3.')
    );
  });

  it('should call onValueChange function', () => {
    const mockOnChange = jest.fn();
    render(<SegmentedControl onValueChange={mockOnChange} options={OPTIONS} />);
    const radio = screen.getByRole('radio', { name: 'Label 2' });
    fireEvent.click(radio);
    expect(mockOnChange).toHaveBeenCalled();
  });
});
